import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{Bn as i,Fn as a,Gn as o,Hn as s,In as c,Kn as l,Ln as u,Rn as d,Un as f,Vn as p,Wn as m,zn as h}from"./chunks/assets.8isJ-IUK.js";var g=JSON.parse(`{"title":"Calculation","description":"","frontmatter":{},"headers":[],"relativePath":"calculation.md","filePath":"calculation.md"}`),_={name:`calculation.md`},v=l+` 1x, `+o+` 2x`,y=m+` 1x, `+f+` 2x`,b=l+` 1x, `+o+` 2x`,x=s+` 1x, `+p+` 2x`,S=i+` 1x, `+h+` 2x`,C=d+` 1x, `+u+` 2x`,w=c+` 1x, `+a+` 2x`;function T(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="calculation" tabindex="-1">Calculation <a class="header-anchor" href="#calculation" aria-label="Permalink to “Calculation”">​</a></h1><p>The calculation tab presents a unified interface that groups the conditions, field formulas, intervals and grids.</p><p>It allow you to pick the different steps and items to implement your custom logic.</p><p><img src="/webp/calculation-items-modal.png-90-1788222277535.webp" srcset="`+v+`" alt="Calculation" title="" width="830" height="588" loading="lazy" style="width:415px;"></p><h2 id="when-you-need-to-use-this-tab" tabindex="-1">When you need to use this tab <a class="header-anchor" href="#when-you-need-to-use-this-tab" aria-label="Permalink to “When you need to use this tab”">​</a></h2><p>In most cases, you don&#39;t need to use this tab. The module will simply execute the default calculation order which is:</p><ol><li><a href="/intervals.html">Intervals</a></li><li><a href="/field-formulas.html">Field formulas</a></li><li><a href="/grids.html">Grids</a></li><li><a href="/conditions.html">Conditions</a></li></ol><p>If you have a more advanced logic, you can use this tab to mix and organize the various items and have the exact calculation order that you want.</p><h2 id="adding-steps" tabindex="-1">Adding steps <a class="header-anchor" href="#adding-steps" aria-label="Permalink to “Adding steps”">​</a></h2><p>First, enable the custom calculation order in the <code>Calculation</code> tab</p><p><img src="/webp/enable-custom-calculation.png-90-1788222277550.webp" srcset="`+y+`" alt="Calculation order" title="" width="710" height="682" loading="lazy" style="width:355px;"></p><p>Then, click on the <code>Add calculation item</code> button and pick the desired type from the dialog</p><p><img src="/webp/calculation-items-modal.png-90-1788222277535.webp" srcset="`+b+`" alt="Calculation" title="" width="830" height="588" loading="lazy" style="width:415px;"></p><p>To add a step, click on one of the buttons, then click &quot;Insert as one step&quot;</p><p><img src="/webp/calculation-items.png-90-1788222277536.webp" srcset="`+x+`" alt="Conditions modal" title="" width="1396" height="632" loading="lazy" style="width:698px;"></p><p>That way, you can easily add the various steps like this</p><p><img src="/webp/calculation-steps.png-90-1788222277536.webp" srcset="`+S+`" alt="Calculation steps" title="" width="1222" height="996" loading="lazy" style="width:611px;"></p><h2 id="adding-items" tabindex="-1">Adding items <a class="header-anchor" href="#adding-items" aria-label="Permalink to “Adding items”">​</a></h2><p>If your logic requires executing, for example, a field formula then an interval then another field formula then you can add individual items from each corresponding dialog and organize them however you like.</p><p>Start by clicking on one of the buttons in the tab footer, then pick from the available items or add a new one.</p><p><img src="/webp/select-field-formulas.png-90-1788222277574.webp" srcset="`+C+`" alt="Select field formulas" title="" width="1568" height="626" loading="lazy" style="width:784px;"></p><p>You can click on the items in the desired order then add them to the calculation.</p><p>You can also add all the items to be able to easily organize them as you need.</p><p>You can also mix the steps and the items freely</p><p><img src="/webp/calculation-items-list.jpg-90-1788222277535.webp" srcset="`+w+`" alt="Calculation items list" title="" width="1594" height="1184" loading="lazy" style="width:797px;"></p><p>In the above example, all the conditions will be interpreted then the specified field formula then the specified grid and so on, thus allowing a finer control over the calculation order.</p><h2 id="reordering-the-items" tabindex="-1">Reordering the items <a class="header-anchor" href="#reordering-the-items" aria-label="Permalink to “Reordering the items”">​</a></h2><p>You can always drag the items to reorganize them. The module will execute the steps from top to bottom in order.</p>`,28)]])}var E=e(_,[[`render`,T]]);export{g as __pageData,E as default};